import type { Role } from '../app'
import type { Record, TableName } from '../db'
import type { SPPage, SPInstance, BootstrapColor } from './SPPage'
import type { sp_rectangle_menu_item } from '../fluent/tables/sp_rectangle_menu_item.now'

type Topic = 'Policies' | 'Applications' | 'General' | 'FAQ' | 'Desktop' | 'News' | 'Email'

type DisplayDate = 'sys_created_on' | 'sys_updated_on' | ''

type PageRef = string | Record<'sp_page'> | SPPage

type MenuType = keyof (typeof sp_rectangle_menu_item)['schema']['type']['choices']

type SPMenuItemConfig = {
    /** Display text for the menu item shown in the portal navigation. */
    label: string
    /**
     * Controls what the menu item links to or displays:
     * - `'page'` — links to an `sp_page` within the portal.
     * - `'url'` — links to an arbitrary internal or external URL.
     * - `'sc_category'` — links to a Service Catalog category listing page.
     * - `'sc_cat_item'` — links directly to a specific catalog item.
     * - `'kb_topic'` — links to a Knowledge Base topic.
     * - `'kb_article'` — links to a specific knowledge article.
     * - `'kb_category'` — links to a Knowledge Base category.
     * - `'filtered'` — displays a filtered list of records from any table.
     * - `'scripted'` — dynamically generates child items via a server-side script.
     * @default 'page'
     */
    type?: MenuType
    /**
     * Sort order of the item within its level (top-level or child items).
     * Lower values appear first (leftmost / topmost).
     * @default 100
     */
    order?: number
    /**
     * Whether this menu item is rendered in the portal navigation.
     * Set to `false` to hide without deleting.
     */
    active?: boolean
    /**
     * Restricts visibility of this menu item to users with at least one of the specified roles.
     * If empty, the item is visible to all users who can access the portal.
     */
    roles?: (string | Role | Record<'sys_user_role'>)[]
    /**
     * FontAwesome icon class (without the `fa-` prefix) displayed alongside the menu item label.
     * @example 'home', 'list', 'question-circle'
     */
    glyph?: string
    /**
     * Bootstrap contextual color applied to the menu item.
     * Valid values: `'default'`, `'primary'`, `'success'`, `'info'`, `'warning'`, `'danger'`.
     */
    color?: BootstrapColor
    /** Tooltip text shown on hover over the menu item. */
    hint?: string
    /** Admin-facing description of the menu item's purpose. Not displayed in the portal UI. */
    shortDescription?: string
    /**
     * GlideRecord encoded query condition evaluated server-side to determine
     * whether this menu item is visible to the current user.
     * @example 'active=true^roles=admin'
     */
    condition?: string
    /**
     * Portal page to navigate to when the item is clicked.
     * Required for types: `'page'`, `'sc_category'`, `'sc_cat_item'`, `'kb_topic'`,
     * `'kb_article'`, `'kb_category'`.
     */
    page?: PageRef
    /**
     * Destination URL for the menu item. Supports absolute and relative URLs.
     * Only used when `type` is `'url'`.
     * @example 'https://example.com', '/nav_to.do?uri=incident_list.do'
     */
    url?: string
    /**
     * HTML `<a target>` attribute controlling how the URL is opened.
     * Only used when `type` is `'url'`.
     * @example '_blank' (new tab), '_self' (same tab)
     */
    urlTarget?: string
    /**
     * Service Catalog category (`sc_category`) this item links to.
     * Only used when `type` is `'sc_category'`.
     */
    scCategory?: string | Record<'sc_category'>
    /**
     * Service Catalog item (`sc_cat_item`) this item links to directly.
     * Only used when `type` is `'sc_cat_item'`.
     */
    catItem?: string | Record<'sc_cat_item'>
    /**
     * Knowledge Base topic the item links to.
     * Valid values: `'Policies'`, `'Applications'`, `'General'`, `'FAQ'`,
     * `'Desktop'`, `'News'`, `'Email'`.
     * Only used when `type` is `'kb_topic'`.
     */
    kbTopic?: Topic
    /**
     * Specific knowledge article (`kb_knowledge`) the item links to.
     * Only used when `type` is `'kb_article'`.
     */
    kbArticle?: string | Record<'kb_knowledge'>
    /**
     * Knowledge Base category (`kb_category`) the item links to.
     * Only used when `type` is `'kb_category'`.
     */
    kbCategory?: string | Record<'kb_category'>
    /**
     * ServiceNow table name from which filtered records are displayed as child items.
     * Only used when `type` is `'filtered'`.
     */
    table?: TableName
    /**
     * Encoded query string used to filter records from `table`.
     * Only used when `type` is `'filtered'`.
     * @example 'active=true^category=software'
     */
    filter?: string
    /**
     * Field name from `table` to display as the primary label for each filtered record.
     * Only used when `type` is `'filtered'`.
     */
    display1?: string
    /**
     * Field name from `table` to display as a secondary label for each filtered record.
     * Only used when `type` is `'filtered'`.
     */
    display2?: string
    /**
     * Date field from `table` to display alongside each filtered record.
     * Valid values: `'sys_created_on'`, `'sys_updated_on'`, `''` (none).
     * Only used when `type` is `'filtered'`.
     */
    displayDate?: DisplayDate
    /**
     * Server-side script that dynamically generates child menu items at runtime.
     * Must return an array of item objects. Only used when `type` is `'scripted'`.
     * Consider using `Now.include()` to move the script to a separate `.js` file.
     */
    script?: ((...args: any[]) => any) | string
}

type LeafMenuItem = Now.Internal.WithID<SPMenuItemConfig & Now.Internal.Meta>

type SPMenuItem = Now.Internal.WithID<SPMenuItemConfig & { childItems?: LeafMenuItem[] } & Now.Internal.Meta>

/** @interface */
export type SPMenu = Now.Internal.WithMetadata<
    SPInstance & {
        /** The menu items for the instance (maps to sp_rectangle_menu_item) */
        items?: SPMenuItem[]
    }
>

/**
 * @group ServicePortal
 */
export function SPMenu(config: SPMenu) {
    return config
}
